"""Fix incomplete Hermes skills: generate docs for frontmatter-present, add stubs for missing."""

import json
import time
import yaml
from pathlib import Path

SKILLS_DIRS = [
    Path.home() / ".hermes/skills/biotech-screener",
    Path.home() / ".hermes/skills/agent-infra",
    Path.home() / ".hermes/skills/autonomous-ai-agents",
]

# Skills with frontmatter but missing docs
NEEDS_DOCS = ["screener-ops"]

# Skills missing frontmatter (need stubs added)
NEEDS_FRONTMATTER = [
    "backtest-framework", "biotech-validation", "financial-health",
    "ic-evaluation", "institutional-signal", "performance-attribution",
    "selector-ranker", "trade-execution", "ai-landscape-monitoring",
