    "openclaw-agent-optimize", "hermes-agent"
]

def parse_skill_md(skill_path: Path):
    """Parse SKILL.md and extract name, description."""
    skill_md = skill_path / "SKILL.md"
    if not skill_md.exists():
        return None, None

    try:
        content = skill_md.read_text()
    except Exception:
        return None, None

    if not content.startswith("---"):
        return None, None

    match = __import__('re').match(r"^---\n(.*?)\n---\n(.*)", content, __import__('re').DOTALL)
    if not match:
        return None, None

    try:
        fm = yaml.safe_load(match.group(1))
        if not isinstance(fm, dict):
            return None, None
        name = fm.get("name", "").strip()
        description = fm.get("description", "").strip()
        if isinstance(description, str):
            description = description.replace("\n", " ").strip()
        if not name or not description:
            return None, None
        return name, description
    except:
        return None, None

def generate_readme(name: str, description: str, category: str) -> str:
    """Generate README.md content."""
    return f"""# {name}

> {description}

## Invoke

```bash
# Slash command in Hermes session
/{name}

# Or preload for full session
hermes -s {name}
```

## When to Use
See SKILL.md for detailed instructions.

## Category
`{category}/{name}`

## Full Documentation
See [SKILL.md](SKILL.md) for complete reference.
"""

def generate_meta_json(name: str) -> str:
    """Generate _meta.json content."""
    meta = {
        "ownerId": "local",
        "slug": name,
        "version": "1.0.0",
        "publishedAt": int(time.time() * 1000),
    }
    return json.dumps(meta, indent=2)

def add_frontmatter_stub(skill_path: Path, name: str):
    """Add minimal YAML frontmatter to SKILL.md."""
    skill_md = skill_path / "SKILL.md"
    content = skill_md.read_text()

    stub = f"""---
name: {name}
description: "{name} skill for the biotech screener. See full documentation below."
tags:
  - biotech-screener
---

"""
    skill_md.write_text(stub + content)

# Fix skills with frontmatter but missing docs
for skill_dir in SKILLS_DIRS:
    if not skill_dir.exists():
        continue

    for skill_path in sorted(skill_dir.iterdir()):
        if not skill_path.is_dir():
            continue

        skill_name = skill_path.name
        if skill_name not in NEEDS_DOCS:
            continue

        name, description = parse_skill_md(skill_path)
        if not name or not description:
            print(f"  ✗ {skill_name} — parse failed (has frontmatter but couldn't extract)")
            continue

        readme_path = skill_path / "README.md"
        meta_path = skill_path / "_meta.json"

        if not readme_path.exists():
            readme_path.write_text(generate_readme(name, description, skill_dir.name))
            print(f"  ✓ {skill_name} — generated README.md")

        if not meta_path.exists():
            meta_path.write_text(generate_meta_json(name))
            print(f"    + {skill_name} — generated _meta.json")

# Add frontmatter stubs to skills missing them
print("\nAdding frontmatter stubs to incomplete SKILL.md files:")
for skill_dir in SKILLS_DIRS:
    if not skill_dir.exists():
        continue

    for skill_path in sorted(skill_dir.iterdir()):
        if not skill_path.is_dir():
            continue

        skill_name = skill_path.name
        if skill_name not in NEEDS_FRONTMATTER:
            continue

        skill_md = skill_path / "SKILL.md"
        if not skill_md.exists():
            print(f"  ⊘ {skill_name} — SKILL.md missing")
            continue

        content = skill_md.read_text()
        if content.startswith("---"):
            print(f"  ⊘ {skill_name} — already has frontmatter")
            continue

        try:
            add_frontmatter_stub(skill_path, skill_name)
            print(f"  ✓ {skill_name} — added frontmatter stub")
        except Exception as e:
            print(f"  ✗ {skill_name} — error: {e}")

